--- a/board/static/board.css
+++ b/board/static/board.css
@@ -8,7 +8,7 @@
 .board td { padding: 12px; border-bottom: 1px solid #e3e7eb; }
 .board .num { font-variant-numeric: tabular-nums; }
 .badge { display: inline-block; padding: 4px 10px; border-radius: 4px; font-weight: 600; font-size: 14px; }
-.badge.short { background: #c62828; color: #ffffff; position: relative; top: -46px; }
+.badge.short { background: #c62828; color: #ffffff; }
 .badge.ok { background: #e3f1e5; color: #1f5f2c; }
 .board .row, .board .head { display: grid; grid-template-columns: 1fr 1fr 1fr 1fr 1.3fr; }
 .board [role=cell], .board [role=columnheader] { padding: 12px; border-bottom: 1px solid #e3e7eb; }
